@php
    $setting = function ($key, $default = '') use ($settings) { return old($key, isset($settings[$key]) ? $settings[$key] : $default); };
    $checks = [
        ['Business identity', (bool)$setting('site_name'), 'identity'],
        ['Customer contact', (bool)($setting('phone') || $setting('support_email') || $setting('whatsapp_number')), 'contact'],
        ['Store address', (bool)$setting('shop_address'), 'contact'],
        ['Search description', (bool)$setting('default_meta_description'), 'seo'],
        ['Brand logo', !empty($settings['site_logo']), 'identity'],
    ];
    $complete = collect($checks)->where(1, true)->count();
    $percent = (int)round(($complete / count($checks)) * 100);
    $developmentModeEnabled = (string)$setting('development_mode_enabled', '0') === '1';
@endphp
